class Solution {
public:
    bool queryString(string s, int n) {
        if (n > 2000) return false;
        auto to_bin = [](int x) {
            string b = "";
            while (x > 0) {
                b.push_back((x & 1) ? '1' : '0');
                x >>= 1;
            }
            reverse(b.begin(), b.end());
            return b;
        };
        for (int x = n; x > n / 2; --x) {
            if (s.find(to_bin(x)) == string::npos) {
                return false;
            }
        }
        return true;
    }
};

class Solution {
    public boolean queryString(String s, int n) {
        if (n > 2000) return false;
        for (int x = n; x > n / 2; --x) {
            if (!s.contains(Integer.toBinaryString(x))) {
                return false;
            }
        }
        return true;
    }
}

var queryString = function(s, n) {
    if (n > 2000) return false;
    for (let x = n; x > Math.floor(n / 2); x--) {
        if (!s.includes(x.toString(2))) {
            return false;
        }
    }
    return true;
};
